class Circle:
    def __init__(self, radius):
        self.radius = radius  # 走 setter 校验

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, r):
        if r < 0:
            raise ValueError("半径不能为负")
        self._radius = r

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(2)
print(c.area)      # 12.56636
c.radius = 3
print(c.area)      # 28.27431
c.radius = -1      # ValueError

输出 12.56636 与 28.27431，负半径抛异常。
